import json
import os
import socket
import time
import uuid
from typing import Any, Dict, List, Optional

import boto3


class CloudWatchLogWriter:
    def __init__(
        self,
        log_group_name: str,
        log_stream_name: Optional[str] = None,
        region_name: Optional[str] = None,
    ) -> None:
        self.log_group_name = log_group_name
        self.log_stream_name = log_stream_name or f"app-{socket.gethostname()}-{uuid.uuid4().hex[:8]}"
        self.region_name = region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION")

        self.client = boto3.client("logs", region_name=self.region_name)
        self.sequence_token = None
        self._ensure_log_group_and_stream()

    def _ensure_log_group_and_stream(self) -> None:
        try:
            self.client.create_log_group(logGroupName=self.log_group_name)
        except self.client.exceptions.ResourceAlreadyExistsException:
            pass
        except Exception:
            pass

        try:
            self.client.create_log_stream(
                logGroupName=self.log_group_name,
                logStreamName=self.log_stream_name,
            )
        except self.client.exceptions.ResourceAlreadyExistsException:
            pass
        except Exception:
            pass

    def _refresh_sequence_token(self) -> None:
        response = self.client.describe_log_streams(
            logGroupName=self.log_group_name,
            logStreamNamePrefix=self.log_stream_name,
            orderBy="LogStreamName",
            descending=False,
            limit=1,
        )
        streams = response.get("logStreams", [])
        if streams:
            self.sequence_token = streams[0].get("uploadSequenceToken")

    def write_events(self, request_id: str, events: List[Dict[str, Any]]) -> Dict[str, Any]:
        timestamp_ms = int(time.time() * 1000)
        log_events = []
        for i, event in enumerate(events):
            payload = {
                "request_id": request_id,
                "timestamp": event.get("timestamp", timestamp_ms + i),
                "level": event.get("level", "INFO"),
                "message": event.get("message", ""),
                "service": event.get("service", "application"),
                "extra": event.get("extra", {}),
            }
            log_events.append(
                {
                    "timestamp": int(payload["timestamp"]),
                    "message": json.dumps(payload, separators=(",", ":"), sort_keys=True),
                }
            )

        kwargs = {
            "logGroupName": self.log_group_name,
            "logStreamName": self.log_stream_name,
            "logEvents": log_events,
        }
        if self.sequence_token:
            kwargs["sequenceToken"] = self.sequence_token

        try:
            response = self.client.put_log_events(**kwargs)
        except self.client.exceptions.InvalidSequenceTokenException:
            self._refresh_sequence_token()
            if self.sequence_token:
                kwargs["sequenceToken"] = self.sequence_token
            else:
                kwargs.pop("sequenceToken", None)
            response = self.client.put_log_events(**kwargs)

        self.sequence_token = response.get("nextSequenceToken", self.sequence_token)
        return response

    def query_by_request_id(
        self,
        request_id: str,
        start_time_ms: Optional[int] = None,
        end_time_ms: Optional[int] = None,
        limit: int = 100,
    ) -> List[Dict[str, Any]]:
        filter_pattern = f'"request_id":"{request_id}"'
        kwargs = {
            "logGroupName": self.log_group_name,
            "filterPattern": filter_pattern,
            "limit": limit,
        }
        if start_time_ms is not None:
            kwargs["startTime"] = start_time_ms
        if end_time_ms is not None:
            kwargs["endTime"] = end_time_ms

        response = self.client.filter_log_events(**kwargs)
        results = []
        for event in response.get("events", []):
            message = event.get("message", "")
            try:
                parsed = json.loads(message)
            except Exception:
                parsed = {"message": message}
            parsed["ingestionTime"] = event.get("ingestionTime")
            parsed["logStreamName"] = event.get("logStreamName")
            parsed["timestamp"] = event.get("timestamp")
            results.append(parsed)
        return results


def write_application_logs(
    log_group_name: str,
    request_id: Optional[str] = None,
    events: Optional[List[Dict[str, Any]]] = None,
    log_stream_name: Optional[str] = None,
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    request_id = request_id or uuid.uuid4().hex
    events = events or [
        {"level": "INFO", "message": "request started", "service": "app"},
        {"level": "INFO", "message": "request finished", "service": "app"},
    ]
    writer = CloudWatchLogWriter(
        log_group_name=log_group_name,
        log_stream_name=log_stream_name,
        region_name=region_name,
    )
    response = writer.write_events(request_id=request_id, events=events)
    return {
        "request_id": request_id,
        "log_group_name": log_group_name,
        "log_stream_name": writer.log_stream_name,
        "next_sequence_token": response.get("nextSequenceToken"),
    }
